"""
Vendor Montserrat as a self-contained stylesheet.

A published page cannot reach a font CDN, so the brand face has to travel with
it. This downloads the woff2 files Google Fonts serves and rewrites them as
@font-face rules with base64 data URIs, producing vendor/montserrat.css.

Latin and Latin-Extended subsets are both kept: institution names in the
ranking include Bogazici, Sao Paulo, Ibanez, Tecnologico and similar, whose
accented characters span both ranges.

Montserrat is licensed under the SIL Open Font License, which permits
embedding. Re-run only when the weights in the design tokens change.

Usage:
    python fetch_fonts.py
"""

import base64
import os
import re
import urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
OUTPUT = os.path.join(HERE, 'montserrat.css')

WEIGHTS = '400;500;600;700;800'
CSS_URL = ('https://fonts.googleapis.com/css2?family=Montserrat:wght@%s&display=swap'
           % WEIGHTS)
KEEP_SUBSETS = ('latin', 'latin-ext')

# Google serves woff2 only to browsers that advertise support.
UA = ('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
      '(KHTML, like Gecko) Chrome/120.0 Safari/537.36')


def get(url, binary=False):
    request = urllib.request.Request(url, headers={'User-Agent': UA})
    with urllib.request.urlopen(request, timeout=60) as response:
        payload = response.read()
    return payload if binary else payload.decode('utf-8')


def main():
    css = get(CSS_URL)

    # Each @font-face block is preceded by a /* subset */ comment.
    blocks = re.split(r'/\*\s*([\w-]+)\s*\*/', css)
    pairs = list(zip(blocks[1::2], blocks[2::2]))

    rules = []
    total = 0
    for subset, block in pairs:
        if subset not in KEEP_SUBSETS:
            continue

        url_match = re.search(r"url\((https://[^)]+\.woff2)\)", block)
        weight_match = re.search(r'font-weight:\s*(\d+)', block)
        range_match = re.search(r'unicode-range:\s*([^;]+);', block)
        if not (url_match and weight_match):
            continue

        font = get(url_match.group(1), binary=True)
        total += len(font)
        encoded = base64.b64encode(font).decode('ascii')

        rules.append(
            "@font-face {\n"
            "  font-family: 'Montserrat';\n"
            "  font-style: normal;\n"
            "  font-weight: %s;\n"
            "  font-display: swap;\n"
            "  src: url(data:font/woff2;base64,%s) format('woff2');\n"
            "%s}" % (
                weight_match.group(1),
                encoded,
                '  unicode-range: %s;\n' % range_match.group(1) if range_match else ''
            ))
        print('  %-10s weight %s  %5.1f KB' % (subset, weight_match.group(1),
                                               len(font) / 1024))

    if not rules:
        raise SystemExit('no font faces found -- the CSS format may have changed')

    header = ('/* Montserrat (SIL Open Font License), inlined so the page needs\n'
              '   no network access. Generated by vendor/fetch_fonts.py. */\n\n')
    with open(OUTPUT, 'w', encoding='utf-8') as handle:
        handle.write(header + '\n\n'.join(rules) + '\n')

    print('\nwrote %s (%.1f KB of font data, %.1f KB encoded)'
          % (OUTPUT, total / 1024, os.path.getsize(OUTPUT) / 1024))


if __name__ == '__main__':
    main()
